        id: "s1",
        h2: "Що таке податкова перевірка",
        html: `<p>Податкова перевірка — це передбачена законом форма контролю, під час якої органи Державної податкової служби досліджують дотримання платником вимог податкового та іншого законодавства. Глава 8 Податкового кодексу України (ПКУ) поділяє перевірки на камеральні, документальні (планові та позапланові) і фактичні. Кожен вид має власний предмет, строки та межі повноважень інспекторів.</p>
<p>Камеральна перевірка проводиться у приміщенні органу ДПС на підставі даних декларацій без виходу до платника. Документальна охоплює первинні документи, регістри обліку та господарські операції. Фактична стосується дотримання касової дисципліни, обігу готівки та ліцензування. Розуміння того, з яким саме видом перевірки ви маєте справу, визначає всю подальшу стратегію захисту.</p>
<p>Детальний огляд кожного виду ми навели в матеріалі про <a href="/blog/vydy-podatkovyh-perevirok/">види податкових перевірок</a>, а загальний контекст податкових спорів — на сторінці практики <a href="/practices/tax-law/">податкове право</a>.</p>`,
