<li><b>Прочитати квитанцію.</b> У ній має бути зазначений <strong>конкретний критерій</strong>, за яким зупинено реєстрацію. Якщо критерію немає або є лише загальне формулювання — це вже дефект рішення, і він працює на платника в суді.</li>
