        h2: "Що таке бюджетне відшкодування ПДВ",
        html: `<p><strong>Бюджетне відшкодування</strong> — це повернення платнику з бюджету суми від’ємного значення ПДВ, тобто перевищення податкового кредиту над податковими зобов’язаннями. Порядок визначений <strong>статтею 200 Податкового кодексу України</strong>.</p>
<p>Право на відшкодування виникає не автоматично з появою від’ємного значення. Платник сам обирає, що з ним робити: зарахувати в наступні періоди або заявити до відшкодування — і лише в другому випадку запускається вся процедура з перевірками, Реєстром і Казначейством.</p>
<p>Найчастіше відшкодування заявляють експортери (операції оподатковуються за нульовою ставкою, вхідний ПДВ накопичується) та підприємства з великими капітальними вкладеннями. Для них це не бонус, а оборотні кошти.</p>
<p>Контекст — на сторінці <a href="/practices/tax-law/">податкове право</a>.</p>`,
