        h2: "Класифікація перевірок за ПКУ",
        html: `<p>Податковий кодекс передбачає <strong>три види</strong> перевірок: камеральні, документальні та фактичні. Документальні, своєю чергою, діляться за двома незалежними ознаками, і саме ця двовимірність плутає найбільше.</p>
<table>
<thead><tr><th>Вид</th><th>Де проводиться</th><th>Чи потрібен допуск</th></tr></thead>
<tbody>
<tr><td>Камеральна</td><td>у приміщенні органу, за даними звітності</td><td>ні, платник у ній не бере участі</td></tr>
<tr><td>Документальна невиїзна</td><td>у приміщенні органу</td><td>ні</td></tr>
<tr><td>Документальна виїзна</td><td>за місцем розташування платника</td><td>так</td></tr>
<tr><td>Фактична</td><td>за місцем фактичного провадження діяльності</td><td>так</td></tr>
</tbody>
</table>
<p>Документальна перевірка водночас буває <strong>плановою</strong> (за план-графіком, стаття 77 ПКУ) або <strong>позаплановою</strong> (за підставами статті 78). Тобто одна перевірка одночасно має дві характеристики: виїзна/невиїзна і планова/позапланова — і від цієї пари залежать і строки, і порядок, і можливість не допустити.</p>
<p>План-графік документальних планових перевірок затверджує ДПС і публікує; до плану на 2026 рік включено близько 4,6 тисячі суб’єктів господарювання. Перше, що варто зробити бізнесу, — перевірити, чи є компанія в графіку: планову перевірку можна підготувати, позаплановій зазвичай просто дивуються.</p>
<p>Контекст — на сторінці <a href="/practices/tax-law/">податкове право</a>, а загальний порядок — у матеріалі про <a href="/blog/podatkova-perevirka/">податкову перевірку</a>.</p>`,
