        html: `<p>Документальна перевірка досліджує первинні документи, регістри бухгалтерського обліку, фінансову звітність, податкові декларації та інші документи, пов’язані з обчисленням і сплатою податків.</p>
<p><b>Планова</b> проводиться за план-графіком. Про її проведення платник повідомляється завчасно — не пізніше ніж за 10 календарних днів надсилається копія наказу та письмове повідомлення із зазначенням дати початку.</p>
<p><b>Позапланова</b> проводиться за підставами, визначеними статтею 78 ПКУ: їх перелік закритий. Типові — отримання податкової інформації, що свідчить про порушення; ненадання відповіді на запит органу; подання уточнюючого розрахунку; процедура припинення платника; ненадання документів на письмовий запит.</p>
<p>Різниця між <b>виїзною</b> та <b>невиїзною</b> важлива з одного погляду: виїзна вимагає допуску. Платник має право не допустити перевіряльників, якщо не предʼявлено належно оформлених документів — наказу, направлення на перевірку, службових посвідчень. Але це право з подвійним дном: недопуск за наявності законних підстав є <strong>самостійною підставою для адміністративного арешту майна</strong> за статтею 94 ПКУ. Про механіку арешту — у матеріалі про <a href="/blog/podatkovyj-borg-aresht-rahunkiv/">податковий борг та арешт рахунків</a>.</p>
<p>Тому недопуск — рішення, яке ухвалюється не емоційно на порозі, а після перевірки документів перевіряльників. Якщо документи в порядку, недопуск шкодить сильніше за саму перевірку.</p>`,
