        id: "s5",
        h2: "Фактичні перевірки",
        html: `<p>Фактична перевірка проводиться <strong>за місцем фактичного провадження діяльності</strong> — у магазині, на складі, в кафе, на АЗС. Вона не включається до план-графіка й проводиться без попереднього повідомлення: у цьому її сенс.</p>
<p>Предмет — дотримання порядку розрахункових операцій, ведення касових операцій, наявність ліцензій і дозвільних документів, обіг підакцизних товарів, оформлення трудових відносин із працівниками.</p>
<p>У 2026 році саме фактичні перевірки є основним практичним інструментом контролю щодо РРО, пального, підакцизних товарів і цін. Для бізнесу з роздрібними точками це означає, що готовність має бути постійною, а не до дати.</p>
<p>Що варто зробити заздалегідь:</p>
<ul>
<li>призначити відповідальну особу й дати їй письмові інструкції, що робити при візиті;</li>
<li>тримати на точці копії ліцензій і дозвільних документів;</li>
<li>навчити персонал перевіряти документи перевіряльників і фіксувати їх дані;</li>
<li>забезпечити можливість негайно звʼязатися з юристом.</li>
</ul>
<p>Найчастіша помилка — працівник на точці, який не знає ні своїх прав, ні того, кому дзвонити, і підписує все, що дають.</p>`,
