        h2: "Два шляхи оскарження ППР",
        html: `<p>Після податкового повідомлення-рішення платник має два шляхи: <strong>адміністративне оскарження</strong> до контролюючого органу вищого рівня (стаття 56 ПКУ) або <strong>позов до адміністративного суду</strong>. Вони не виключають один одного: можна спершу пройти адміністративний, а потім судовий.</p>
<p>Але зворотного руху немає — після звернення до суду адміністративна процедура вже недоступна. Тому послідовність обирається один раз і на старті.</p>
<p>Головне, що обʼєднує обидва шляхи: доки триває оскарження, грошове зобовʼязання залишається <strong>неузгодженим</strong>, а отже податкового боргу не виникає й активи не підлягають стягненню. Механіку ми розібрали в матеріалі про <a href="/blog/podatkovyj-borg-aresht-rahunkiv/">податковий борг та арешт рахунків</a>.</p>
<p>Контекст — на сторінці <a href="/practices/tax-law/">податкове право</a>, а загальний порядок оскарження — у матеріалі про <a href="/blog/oskarzhennya-ppr/">оскарження ППР</a>.</p>`,
