<li><b>Перевірити процедуру перевірки.</b> Наказ, направлення, строки, предмет: виходи за межі предмета та порушення строків оцінюються судом, але лише якщо зафіксовані. Види перевірок і строки — у матеріалі про <a href="/blog/vydy-podatkovyh-perevirok/">види податкових перевірок</a>.</li>
