<p>Остання позиція визначає результат. Пакет «про те, що ми добросовісні» без адресації конкретного критерію комісія розглядає формально. Тому перший документ, який потрібен, — це саме рішення про відповідність критеріям із зазначенням, якому саме критерію платник відповідає.</p>
