        h2: "Критерії: за що потрапляють",
        html: `<p>Перелік критеріїв ризиковості платника затверджений урядовим порядком і є <b>вичерпним</b>. Комісія не може вигадати підставу поза цим переліком.</p>
<p>Умовно критерії діляться на дві групи.</p>
<p><b>Формальні — очевидні й безспірні:</b></p>
<ul>
<li>реєстрація на недійсні або втрачені документи;</li>
<li>реєстрація на осіб, які не мали наміру провадити діяльність, або без відома засновників;</li>
<li>переоформлення на підставних осіб;</li>
<li>відсутність відкритих рахунків у банках;</li>
<li>неподання звітності з ПДВ за останні звітні періоди;</li>
<li>неподання звітності з податку на прибуток за останній період.</li>
</ul>
<p>Ці підстави усуваються механічно: подати звітність, відкрити рахунок, виправити реєстраційні дані. Якщо ваш випадок тут — це найпростіший сценарій.</p>
<p><b>Оцінний — той, за яким потрапляє більшість:</b> наявність податкової інформації, що свідчить про ризиковість здійснення операцій. Про нього окремо нижче, бо саме він створює всі складні справи.</p>`,
