<p>Головна практична пастка — у другій групі. ФОП другої групи <strong>не може надавати послуги юридичній особі на загальній системі оподаткування</strong>. Це найчастіша причина, через яку підприємця позбавляють права на спрощену систему: він працює на 2 групі, укладає договір із ТОВ на загальній системі, і одна така операція ламає статус.</p>
