<p>Третя складова — <strong>єдиний соціальний внесок</strong>: 22 % від бази, і мінімальний страховий платіж розраховується від мінімальної заробітної плати. На 2026 рік це приблизно 1 902 ₴ на місяць, тобто близько 22,8 тис ₴ за рік.</p>
