        h2: "Порядок стягнення боргу",
        html: `<p>Стягнення податкового боргу відбувається послідовно, а не одним рухом. Загальна логіка така.</p>
<ol>
<li><b>Кошти на рахунках.</b> Стягнення коштів здійснюється <strong>на підставі рішення суду</strong>, за зверненням контролюючого органу. Самостійно списати кошти з рахунку податковий орган не може.</li>
<li><b>Інше майно.</b> Продаж майна, що перебуває в податковій заставі, можливий не раніше ніж через 30 календарних днів з дня вручення податкової вимоги.</li>
<li><b>Дебіторська заборгованість.</b> ПКУ дозволяє використати як джерело погашення боргу дебіторську заборгованість платника, строк погашення якої настав, — за договором відступлення на користь контролюючого органу.</li>
<li><b>Фізичні особи.</b> Стягнення з фізичної особи здійснюється за рішенням суду, яке виконується державною виконавчою службою в порядку виконавчого провадження.</li>
</ol>
<p>Альтернатива примусовому стягненню існує й працює: розстрочення та відстрочення грошових зобов’язань і податкового боргу за наявності належних підстав. Про цей механізм — у матеріалі про <a href="/blog/podatkovyj-kompromis/">податковий компроміс</a>, а про суми фінансових санкцій — у статті про <a href="/blog/shtrafy-dps/">штрафи ДПС</a>.</p>
<p>Практичне спостереження: домовитися про розстрочення до арешту значно легше, ніж знімати арешт після. Коли майно вже обтяжене, позиція платника в переговорах слабша, а частина контрагентів уже бачить обтяження в реєстрі.</p>`,
