<p>Ми оскаржуємо рішення про арешт і податкову заставу, доводимо відсутність підстав за статтею 94 ПКУ, заперечуємо позови про стягнення коштів і захищаємо рахунки бізнесу від необґрунтованого стягнення в межах практики <a href="/practices/litigation/">судових спорів</a>.</p>
