        html: `<p>Розділення діяльності між кількома юридичними особами — законний інструмент, якщо в основі лежить не податкова вигода, а управлінська логіка.</p>
<p>Коли структурування виглядає обґрунтованим:</p>
<ul>
<li><b>Різні напрями діяльності</b> з різними ризиками — виробництво і роздріб, послуги та оренда.</li>
<li><b>Різні партнери</b> в різних проєктах.</li>
<li><b>Ізоляція активів</b> — нерухомість в одній компанії, операційна діяльність в іншій, щоб операційні ризики не досягали майна.</li>
<li><b>Підготовка до продажу</b> частини бізнесу або до входження інвестора.</li>
<li><b>Різні регуляторні вимоги</b> — ліцензовані та неліцензовані напрями.</li>
</ul>
<p>Про побудову таких конструкцій ми пишемо в матеріалі про <a href="/blog/kholdyngova-struktura/">холдингову структуру</a>. Операції між пов’язаними компаніями потребують окремої уваги — див. <a href="/blog/transfertne-cinoutvorennya/">трансфертне ціноутворення</a>.</p>`,
