<p>Окремо про ситуацію, коли <strong>до вас приходять для звірки</strong>: забезпечте, щоб за юридичною адресою була особа, яка приймає документи й знає, що робити. Акт про неможливість звірки часто складається не через відмову, а через те, що за адресою нікого не виявилося.</p>
